// Example of correlating logs with traces using MDC
import org.slf4j.MDC;

public void processRequest(Request req) {
    String traceId = Span.current().getSpanContext().getTraceId();
    MDC.put("traceId", traceId);
    try {
        log.info("Processing request: {}", req.getId());
        meterRegistry.counter("requests.processed").increment();
        // Business logic here
    } finally {
        MDC.remove("traceId");
    }
}
